function Defs({ theme }: { theme: Theme }) {
  const uid = theme.id;
  return (
    <defs>
      <linearGradient id={`frame-${uid}`} x1="31" y1="59" x2="629" y2="445">
        <stop stopColor={FRAME.frameFrom} />
        <stop offset="0.24" stopColor={FRAME.frameMid} />
        <stop offset="1" stopColor={FRAME.frameTo} />
      </linearGradient>
      <linearGradient id={`chrome-${uid}`} x1="31" y1="7.637" x2="63.75" y2="170.953">
        <stop stopColor={FRAME.chrome} />
        <stop offset="1" stopColor={FRAME.chrome} />
      </linearGradient>
      <radialGradient
        id={`glow-${uid}`}
        cx="0"
        cy="0"
        r="1"
        gradientTransform="translate(242 142) rotate(90) scale(269 348)"
      >
        <stop stopColor={theme.glow} />
        <stop offset="0.4" stopColor={theme.glowMid} stopOpacity="0.9" />
        <stop offset="0.8" stopColor={FRAME.frameMid} stopOpacity="0.32" />
        <stop offset="1" stopColor={FRAME.frameTo} stopOpacity="0" />
      </radialGradient>
      <linearGradient id={`accent-${uid}`} x1="0" y1="0" x2="1" y2="1">
        <stop stopColor={theme.accent} />
        <stop offset="1" stopColor={theme.accentSoft} />
      </linearGradient>
      <linearGradient id={`cta-${uid}`} x1="0" y1="0" x2="1" y2="0">
        <stop stopColor="#EC4899" />
        <stop offset="1" stopColor="#8B5CF6" />
      </linearGradient>
      <linearGradient id={`panel-${uid}`} x1="0" y1="0" x2="1" y2="1">
        <stop stopColor={theme.accentSoft} stopOpacity="0.35" />
        <stop offset="1" stopColor={theme.card} stopOpacity="0.15" />
      </linearGradient>
      <clipPath id={`clip-${uid}`}>
        <rect width="574" height="394" />
      </clipPath>
      <clipPath id={`body-${uid}`}>
        <path d="M573.5 51.5V364C573.5 380.292 560.292 393.5 544 393.5H30C13.7076 393.5 0.5 380.292 0.5 364V51.5H573.5Z" />
      </clipPath>
    </defs>
  );
}

