function MockupSvg({
  theme,
  content,
}: {
  theme: Theme;
  content: "blue" | "purple" | "green" | "orange";
}) {
  return (
    <svg
      width="574"
      height="394"
      viewBox="0 0 574 394"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className="h-full w-full"
      aria-hidden
    >
      <Defs theme={theme} />
      <g clipPath={`url(#clip-${theme.id})`}>
        <BrowserChrome theme={theme} />
        <g clipPath={`url(#body-${theme.id})`}>
          {content === "blue" ? <ContentBlue theme={theme} /> : null}
          {content === "purple" ? <ContentPurple theme={theme} /> : null}
          {content === "green" ? <ContentGreen theme={theme} /> : null}
          {content === "orange" ? <ContentOrange theme={theme} /> : null}
        </g>
      </g>
    </svg>
  );
}

export function MockupVariantBlue() {
  return <MockupSvg theme={themes.blue} content="blue" />;
}
export function MockupVariantPurple() {
  return <MockupSvg theme={themes.purple} content="purple" />;
}
export function MockupVariantGreen() {
  return <MockupSvg theme={themes.green} content="green" />;
}
export function MockupVariantOrange() {
  return <MockupSvg theme={themes.orange} content="orange" />;
}
